def transform(grid):
    # Complete the outer rectangle around the sparse pattern with color 2.
    h, w = len(grid), len(grid[0])
    mark = next(v for row in grid for v in row if v not in (7,))
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == mark]
    r0 = min(r for r, c in points)
    r1 = max(r for r, c in points)
    c0 = min(c for r, c in points)
    c1 = max(c for r, c in points)
    out = [row[:] for row in grid]
    for c in range(c0, c1 + 1):
        if out[r0][c] != mark:
            out[r0][c] = 2
        if out[r1][c] != mark:
            out[r1][c] = 2
    for r in range(r0, r1 + 1):
        if out[r][c0] != mark:
            out[r][c0] = 2
        if out[r][c1] != mark:
            out[r][c1] = 2
    return out
